            out[str(v).strip().lower()] = c
    return out

def sample_from_variant_name(name):
    m = re.search(r'CHIP_(.+?)\\.xlsx"'$'"', name)
    if not m:
        return ''
    label = m.group(1).strip()
    return label.split('-')[0].strip()

manifest_path, result_path = sys.argv[1], sys.argv[2]
