exclude_terms = ['intron', 'intergenic', 'utr']

numerator = 0
denominator = 0
processed_carrier_files = 0
carrier_files = []
missing_carrier_samples = sorted([x for x in carriers if x.isdigit()])
per_sample = {}
classification_counts = {}

for name in sorted(name_to_path):
    if not name.startswith('230209_Exome_GRCh38_CHIP_'):
        continue
    sample = sample_from_variant_name(name)
    if sample not in carriers:
        continue
    processed_carrier_files += 1
    carrier_files.append(name)
