    hdr = header_index(ws)
    for req in required:
        if req not in hdr:
            raise RuntimeError('Missing required column %s in %s' % (req, name))
    zcol = hdr['zygosity']
    vafcol = hdr['variant allele freq']
    genecol = hdr['gene names']
    socol = hdr['sequence ontology (combined)']
    ccol = hdr['classification']
    s_num = 0
    s_den = 0
    for r in range(3, ws.max_row + 1):
        zyg = as_text(cell(ws, r, zcol)).lower()
        if not zyg or zyg == 'reference':
            continue
        vaf = parse_float(cell(ws, r, vafcol))
        if vaf is None or not (vaf < 0.3):
            continue
        genes = gene_tokens(cell(ws, r, genecol))
        if not genes.intersection(chip_genes):
            continue
        so = as_text(cell(ws, r, socol)).lower()
        if any(term in so for term in exclude_terms):
            continue
        classification = as_text(cell(ws, r, ccol))
        if not classification:
            continue
        c_norm = classification.lower().replace('_', ' ').strip()
        denominator += 1
        s_den += 1
        classification_counts[c_norm] = classification_counts.get(c_norm, 0) + 1
        if c_norm in benign_classes:
            numerator += 1
            s_num += 1
    if s_den or s_num:
        per_sample[sample] = {'benign_likely_benign': s_num, 'classified_filtered_variants': s_den}

proportion = (float(numerator) / float(denominator)) if denominator else float('nan')
with open(result_path, 'w') as out:
    out.write('metric\\tvalue\\n')
    out.write('numerator\\t%d\\n' % numerator)
    out.write('denominator\\t%d\\n' % denominator)
    out.write('proportion\\t%.12g\\n' % proportion)
    out.write('processed_carrier_files\\t%d\\n' % processed_carrier_files)
    out.write('carrier_samples_in_status\\t%d\\n' % len(carriers))
    out.write('missing_numeric_carrier_samples_after_file_match\\t%s\\n' % ','.join(missing_carrier_samples))
